"use strict";(globalThis.webpackChunkmy_website||=[]).push([[97544],{28923(a){a.exports=JSON.parse('{"slug":"treasury-donation","title":"Treasury Donation","short":"A transaction that sends ada directly into the Cardano treasury, increasing the funds the community can later allocate.","category":"governance","aliases":["Treasury Donate","Donate to Treasury"],"mentalModel":null,"related":["treasury","treasury-withdrawal","governance-action","conway-era"],"sources":[],"link":"/governance/treasury#donate","level":"intermediate","body":"A treasury donation is a Conway-era transaction that adds ada straight to the Cardano treasury instead of paying it to a recipient address. The amount is recorded in the transaction\'s `donation` field, so the funds leave the sender\'s wallet and join the treasury pot that the community later allocates through on-chain governance.\\n\\nAnyone can make one from a CIP-30 wallet. You can build, sign, and submit a treasury donation directly on cardano.org: [Donate to the treasury](/governance/treasury#donate)."}')}}]);